    {
        "technology_slug": "terraform",
        "title": "Terraform Fundamentals: Init, Plan, Apply",
        "slug": "terraform-fundamentals",
        "architecture_type": "custom",
        "description": (
            "Learn the Terraform core loop. Write your first configuration, understand providers and the "
            "state file, use variables and outputs, and walk the init → plan → apply → destroy lifecycle. "
            "Everything else in IaC builds on this."
        ),
        "objectives": [
            "Write HCL with providers and resources",
            "Run the init/plan/apply/destroy lifecycle",
            "Parameterise with variables and expose outputs",
            "Understand and inspect Terraform state",
        ],
        "difficulty": "beginner",
        "estimated_hours": 3,
        "order": 1,
        "tasks": [
            {
                "jira_key": "TF-1",
                "title": "Write your first configuration",
                "description": "Create main.tf declaring a provider and a single resource (e.g. a local file or a null_resource).",
                "acceptance_criteria": "`terraform init` succeeds and downloads the provider.",
                "hint": "Add a `terraform { required_providers {...} }` block and a `provider` block. Start with the `local` provider's `local_file` resource — no cloud account needed.",
                "order": 1,
            },
            {
                "jira_key": "TF-2",
                "title": "Plan and apply",
                "description": "Run a plan to preview the change, then apply it and verify the resource was created.",
                "acceptance_criteria": "`terraform apply` creates the resource; `terraform show` reflects it in state.",
                "hint": "`terraform plan -out=tf.plan` then `terraform apply tf.plan`. The plan is the source of truth for what apply will do.",
                "order": 2,
                "depends_on": "TF-1",
            },
            {
                "jira_key": "TF-3",
                "title": "Parameterise with variables",
                "description": "Extract hardcoded values into input variables with types and defaults, and pass one via a tfvars file.",
                "acceptance_criteria": "Changing a variable in terraform.tfvars changes the planned resource.",
                "hint": "Declare `variable \"name\" { type = string }`, reference with `var.name`, and set values in terraform.tfvars or `-var`.",
                "order": 3,
                "depends_on": "TF-2",
            },
            {
                "jira_key": "TF-4",
                "title": "Expose outputs",
                "description": "Add output values that surface useful attributes of your resources after apply.",
                "acceptance_criteria": "`terraform output` prints the declared values.",
                "hint": "Add `output \"path\" { value = local_file.x.filename }`. Outputs are also how modules return data to callers.",
                "order": 4,
                "depends_on": "TF-2",
            },
            {
                "jira_key": "TF-5",
                "title": "Inspect and understand state",
                "description": "Examine the state file, list resources, and show a single resource's attributes.",
                "acceptance_criteria": "`terraform state list` and `terraform state show <addr>` return your resources.",
                "hint": "State maps config to real resources. Never edit terraform.tfstate by hand — use `terraform state` subcommands. Treat it as sensitive.",
                "order": 5,
                "depends_on": "TF-2",
            },
            {
                "jira_key": "TF-6",
                "title": "Destroy cleanly",
                "description": "Tear down everything Terraform created and confirm state is empty.",
                "acceptance_criteria": "`terraform destroy` removes all resources; `terraform state list` is empty.",
                "hint": "`terraform destroy` (review the plan first). It only destroys what's in state — drift created outside Terraform won't be touched.",
                "order": 6,
                "depends_on": "TF-2",
            },
        ],
    },
    {
        "technology_slug": "terraform",
        "title": "Reusable Modules & Composition",
        "slug": "terraform-module-design",
        "architecture_type": "custom",
        "description": (
            "Stop copy-pasting HCL. Design a reusable module with a clean input/output contract, version and "
            "source it, compose multiple modules together, and validate with fmt/validate. Modules are how "
            "Terraform scales across a team."
        ),
        "objectives": [
            "Design a module with variables, outputs, and sane defaults",
            "Consume a module with source and version pinning",
            "Compose multiple modules into a root configuration",
            "Enforce style and correctness with fmt and validate",
        ],
        "difficulty": "intermediate",
        "estimated_hours": 4,
        "order": 2,
        "tasks": [
            {
                "jira_key": "TFM-1",
                "title": "Extract a module",
                "description": "Move a repeated set of resources into modules/network with its own variables.tf and outputs.tf.",
                "acceptance_criteria": "The module directory has main/variables/outputs and is self-contained.",
                "hint": "A module is just a directory of .tf files. Define inputs in variables.tf, return values in outputs.tf. Keep it focused on one concern.",
                "order": 1,
            },
            {
                "jira_key": "TFM-2",
                "title": "Call the module from root",
                "description": "Reference the module from the root configuration and pass required inputs.",
                "acceptance_criteria": "`terraform init` initialises the module; plan shows the module's resources.",
                "hint": "Use a `module \"network\" { source = \"./modules/network\" ... }` block. Run `terraform init` again whenever you add/move modules.",
                "order": 2,
                "depends_on": "TFM-1",
            },
            {
                "jira_key": "TFM-3",
                "title": "Pin module versions",
                "description": "Pin the module (and providers) to explicit versions for reproducible builds.",
                "acceptance_criteria": "Module and provider versions are constrained; init resolves them deterministically.",
                "hint": "For registry/remote modules use `version = \"~> 1.2\"`. Pin providers in required_providers. Commit the .terraform.lock.hcl.",
                "order": 3,
                "depends_on": "TFM-2",
            },
            {
                "jira_key": "TFM-4",
                "title": "Compose multiple modules",
                "description": "Add a second module (e.g. compute) and wire its inputs from the network module's outputs.",
                "acceptance_criteria": "The compute module consumes the network module's outputs via references.",
                "hint": "Pass `subnet_id = module.network.subnet_id`. Terraform infers dependency order from these references — no explicit ordering needed.",
                "order": 4,
                "depends_on": "TFM-2",
            },
            {
                "jira_key": "TFM-5",
                "title": "Use count/for_each for multiples",
                "description": "Use for_each to instantiate several similar resources (e.g. multiple subnets) from a map.",
                "acceptance_criteria": "Adding an entry to the input map creates one more resource on the next apply.",
                "hint": "`for_each = var.subnets` then reference `each.key`/`each.value`. Prefer for_each over count for stable addressing when items can be removed.",
                "order": 5,
                "depends_on": "TFM-1",
            },
            {
                "jira_key": "TFM-6",
                "title": "Enforce fmt and validate",
                "description": "Run terraform fmt and validate, and add them as a pre-commit gate.",
                "acceptance_criteria": "`terraform fmt -check` and `terraform validate` both pass with no changes.",
                "hint": "`terraform fmt -recursive` canonicalises style; `terraform validate` checks internal consistency. Wire both into CI/pre-commit.",
                "order": 6,
                "depends_on": "TFM-2",
            },
        ],
    },
