    {
        "technology_slug": "database",
        "title": "Database Fundamentals: Install, Model & Query",
        "slug": "database-fundamentals",
        "architecture_type": "custom",
        "description": (
            "Start your DBA journey. Install a relational database, create a schema with sensible types and "
            "constraints, load data, and write the core SQL you'll use every day. The foundation for all the "
            "database projects that follow."
        ),
        "objectives": [
            "Install and connect to a relational database",
            "Design tables with keys, types, and constraints",
            "Write SELECT/INSERT/UPDATE/DELETE and JOINs",
            "Use transactions for atomic changes",
        ],
        "difficulty": "beginner",
        "estimated_hours": 3,
        "order": 1,
        "tasks": [
            {
                "jira_key": "DB-1",
                "title": "Install and connect",
                "description": "Install PostgreSQL, start it, and connect with psql to create a database `shopdb`.",
                "acceptance_criteria": "`psql -d shopdb -c 'SELECT version();'` succeeds.",
                "hint": "Install postgresql-server, initdb, start the service, then `createdb shopdb` and connect with `psql shopdb`.",
                "order": 1,
            },
            {
                "jira_key": "DB-2",
                "title": "Design the schema",
                "description": "Create customers, products, and orders tables with primary keys, foreign keys, and NOT NULL constraints.",
                "acceptance_criteria": "The three tables exist with PK/FK relationships enforced.",
                "hint": "Use appropriate types (e.g. serial/identity PKs, numeric for money, timestamptz). FKs enforce referential integrity — orders.customer_id REFERENCES customers.",
                "order": 2,
                "depends_on": "DB-1",
            },
            {
                "jira_key": "DB-3",
                "title": "Load sample data",
                "description": "Insert customers and products, then create a few orders referencing them.",
                "acceptance_criteria": "All tables have rows and FK constraints are satisfied.",
                "hint": "INSERT parents before children (customers/products before orders). Bulk-load with `COPY` for larger datasets.",
                "order": 3,
                "depends_on": "DB-2",
            },
            {
                "jira_key": "DB-4",
                "title": "Query with JOINs and aggregates",
                "description": "Write queries joining orders to customers/products and aggregate revenue per customer.",
                "acceptance_criteria": "A query returns total revenue per customer ordered descending.",
                "hint": "Use INNER JOIN to connect tables, GROUP BY customer, SUM the amounts, ORDER BY the total DESC.",
                "order": 4,
                "depends_on": "DB-3",
            },
            {
                "jira_key": "DB-5",
                "title": "Use a transaction",
                "description": "Place an order and decrement stock atomically so a failure leaves no partial change.",
                "acceptance_criteria": "If either statement fails, the whole transaction rolls back.",
                "hint": "Wrap the statements in BEGIN ... COMMIT; on error, ROLLBACK. ACID atomicity means all-or-nothing.",
                "order": 5,
                "depends_on": "DB-3",
            },
            {
                "jira_key": "DB-6",
                "title": "Create a constraint and a view",
                "description": "Add a CHECK constraint (e.g. quantity > 0) and a view summarising daily sales.",
                "acceptance_criteria": "Invalid inserts are rejected; the view returns daily totals.",
                "hint": "`ALTER TABLE ... ADD CONSTRAINT ... CHECK (quantity > 0)`. Create a view with `CREATE VIEW daily_sales AS SELECT ...`.",
                "order": 6,
                "depends_on": "DB-2",
            },
        ],
    },
    {
        "technology_slug": "database",
        "title": "Indexing & Query Performance Tuning",
        "slug": "database-indexing-performance",
        "architecture_type": "custom",
        "description": (
            "Make slow queries fast. Read execution plans, add the right indexes (and avoid the wrong ones), "
            "fix N+1 patterns, and tune the database for throughput. Performance is where DBAs earn their "
            "keep."
        ),
        "objectives": [
            "Read and interpret EXPLAIN ANALYZE output",
            "Add B-tree, composite, and partial indexes appropriately",
            "Eliminate full scans and N+1 access patterns",
            "Maintain statistics and understand the planner",
        ],
        "difficulty": "advanced",
        "estimated_hours": 4,
        "order": 2,
        "tasks": [
            {
                "jira_key": "DBP-1",
                "title": "Baseline with a large dataset",
                "description": "Generate a large table and capture a slow query's execution time as a baseline.",
                "acceptance_criteria": "You have a reproducible slow query with a recorded baseline timing.",
                "hint": "Use `generate_series` to create lots of rows. Time the query with `\\timing` on, before any indexes.",
                "order": 1,
            },
            {
                "jira_key": "DBP-2",
                "title": "Read the execution plan",
                "description": "Run EXPLAIN ANALYZE and identify the costly operations (seq scans, sorts, nested loops).",
                "acceptance_criteria": "You can point to the seq scan / sort that dominates the cost.",
                "hint": "`EXPLAIN (ANALYZE, BUFFERS) <query>`. Look for Seq Scan on big tables, expensive Sort, and rows estimated vs actual.",
                "order": 2,
                "depends_on": "DBP-1",
            },
            {
                "jira_key": "DBP-3",
                "title": "Add a targeted index",
                "description": "Create an index that turns the seq scan into an index scan and re-measure.",
                "acceptance_criteria": "The query uses the index and runs dramatically faster.",
                "hint": "Index the column(s) in the WHERE/JOIN predicate. Re-run EXPLAIN to confirm an Index Scan replaced the Seq Scan.",
                "order": 3,
                "depends_on": "DBP-2",
            },
            {
                "jira_key": "DBP-4",
                "title": "Use a composite/covering index",
                "description": "Create a multi-column index that satisfies a query from the index alone (index-only scan).",
                "acceptance_criteria": "The plan shows an Index Only Scan with no heap fetches.",
                "hint": "Order composite index columns by selectivity/usage; INCLUDE extra columns to cover the SELECT list. Column order matters for range vs equality.",
                "order": 4,
                "depends_on": "DBP-3",
            },
            {
                "jira_key": "DBP-5",
                "title": "Avoid over-indexing",
                "description": "Identify a redundant/unused index and drop it, explaining the write-amplification cost.",
                "acceptance_criteria": "An unused index is removed and writes are unaffected functionally.",
                "hint": "Check `pg_stat_user_indexes` for idx_scan=0. Every index slows INSERT/UPDATE and uses space — keep only those that earn their cost.",
                "order": 5,
                "depends_on": "DBP-3",
            },
            {
                "jira_key": "DBP-6",
                "title": "Refresh statistics and re-plan",
                "description": "Run ANALYZE/VACUUM and show how fresh statistics change the planner's choices.",
                "acceptance_criteria": "After ANALYZE, plan estimates align better with actual row counts.",
                "hint": "`ANALYZE table;` updates planner stats; `VACUUM` reclaims dead tuples. Stale stats cause bad plans. Autovacuum usually handles this in prod.",
                "order": 6,
                "depends_on": "DBP-2",
            },
        ],
    },
    {
        "technology_slug": "database",
        "title": "Backup, PITR & Disaster Recovery",
        "slug": "database-backup-pitr-dr",
        "architecture_type": "custom",
        "description": (
            "Never lose data. Take logical and physical backups, enable continuous archiving for "
            "point-in-time recovery, and rehearse restores including recovering to a specific moment before a "
            "bad transaction. The single most important DBA skill."
        ),
        "objectives": [
            "Take logical and physical backups",
            "Enable WAL archiving for continuous backup",
            "Restore a full backup and verify integrity",
            "Perform point-in-time recovery to before an error",
        ],
        "difficulty": "advanced",
        "estimated_hours": 5,
        "order": 3,
        "tasks": [
            {
                "jira_key": "DBR-1",
                "title": "Take a logical backup",
                "description": "Dump the database with pg_dump and confirm the archive contains the schema and data.",
                "acceptance_criteria": "A pg_dump archive exists and lists the expected objects.",
                "hint": "`pg_dump -Fc shopdb > shopdb.dump`. The custom format (-Fc) supports selective restore with pg_restore.",
                "order": 1,
            },
            {
                "jira_key": "DBR-2",
                "title": "Restore to a new database",
                "description": "Restore the dump into a fresh database and verify row counts match.",
                "acceptance_criteria": "The restored database matches the source row counts.",
                "hint": "`createdb shopdb_restore` then `pg_restore -d shopdb_restore shopdb.dump`. Compare counts of key tables to validate.",
                "order": 2,
                "depends_on": "DBR-1",
            },
            {
                "jira_key": "DBR-3",
                "title": "Take a physical base backup",
                "description": "Use pg_basebackup to capture a physical copy of the cluster.",
                "acceptance_criteria": "A consistent base backup of the data directory is produced.",
                "hint": "`pg_basebackup -D /backups/base -Fp -Xs -P`. Physical backups underpin replication and PITR.",
                "order": 3,
            },
            {
                "jira_key": "DBR-4",
                "title": "Enable WAL archiving",
                "description": "Turn on continuous WAL archiving so every change after the base backup is captured.",
                "acceptance_criteria": "WAL segments are being archived to the archive location.",
                "hint": "Set `wal_level=replica`, `archive_mode=on`, and an `archive_command` that copies WAL safely. Confirm segments appear in the archive.",
                "order": 4,
                "depends_on": "DBR-3",
            },
            {
                "jira_key": "DBR-5",
                "title": "Simulate a bad transaction",
                "description": "Record the current time, then run a destructive statement (e.g. accidental mass DELETE).",
                "acceptance_criteria": "You have a timestamp just before the destructive change.",
                "hint": "Note `SELECT now();` before the bad DELETE. That timestamp is your PITR target — recover to just before it.",
                "order": 5,
                "depends_on": "DBR-4",
            },
            {
                "jira_key": "DBR-6",
                "title": "Perform point-in-time recovery",
                "description": "Restore the base backup and replay WAL up to just before the bad transaction.",
                "acceptance_criteria": "The recovered database contains the data as it was before the destructive change.",
                "hint": "Restore the base backup, set `recovery_target_time` to your timestamp, provide a `restore_command`, and start in recovery. Verify the deleted rows are back.",
                "order": 6,
                "depends_on": "DBR-5",
            },
        ],
    },
