    {
        "technology_slug": "devops",
        "title": "SRE Capstone: Reliability, Load Testing & Incident Response",
        "slug": "devops-sre-capstone",
        "architecture_type": "custom",
        "description": (
            "Operate a service like an SRE. Define SLOs and error budgets, load-test to find limits, add "
            "autoscaling and graceful degradation, run a chaos/game-day exercise, and write a postmortem. The "
            "DevOps zero-to-hero capstone."
        ),
        "objectives": [
            "Define SLIs/SLOs and error budgets",
            "Load-test to find capacity limits",
            "Add autoscaling and graceful degradation",
            "Run an incident game-day and write a postmortem",
        ],
        "difficulty": "advanced",
        "estimated_hours": 6,
        "order": 5,
        "tasks": [
            {
                "jira_key": "SRE-1",
                "title": "Define SLIs and SLOs",
                "description": "Pick service-level indicators and set realistic objectives with an error budget.",
                "acceptance_criteria": "Documented SLIs/SLOs with an explicit error budget exist.",
                "hint": "SLIs: availability, latency. SLO: e.g. 99.9% over 30d. Error budget = 1 - SLO. The budget governs how much risk you can take.",
                "order": 1,
            },
            {
                "jira_key": "SRE-2",
                "title": "Load-test the service",
                "description": "Run a load test ramping traffic to find the throughput and latency knee.",
                "acceptance_criteria": "You identify the request rate at which latency/errors degrade.",
                "hint": "Use k6/Locust to ramp load. Watch where p95 latency and error rate climb — that's your capacity limit.",
                "order": 2,
                "depends_on": "SRE-1",
            },
            {
                "jira_key": "SRE-3",
                "title": "Add autoscaling",
                "description": "Configure autoscaling so the service adds capacity under load and removes it when idle.",
                "acceptance_criteria": "Under load the service scales out; load removal scales it back in.",
                "hint": "Scale on a leading signal (CPU/RPS/latency). Re-run the load test to confirm it keeps SLOs under the previous breaking load.",
                "order": 3,
                "depends_on": "SRE-2",
            },
            {
                "jira_key": "SRE-4",
                "title": "Add graceful degradation",
                "description": "Add timeouts, retries with backoff, and a circuit breaker / fallback for a dependency.",
                "acceptance_criteria": "When a dependency fails, the service degrades gracefully instead of cascading.",
                "hint": "Set client timeouts, bounded retries with jitter, and a circuit breaker. Fail fast and shed load rather than collapse.",
                "order": 4,
                "depends_on": "SRE-2",
            },
            {
                "jira_key": "SRE-5",
                "title": "Run a chaos game-day",
                "description": "Inject a failure (kill an instance, add latency) and observe detection and recovery.",
                "acceptance_criteria": "The failure is detected by alerts and the system recovers within target.",
                "hint": "Announce a game-day, inject one controlled failure, and time detection→mitigation→recovery. Validate your alerts actually fire.",
                "order": 5,
                "depends_on": "SRE-3",
            },
            {
                "jira_key": "SRE-6",
                "title": "Write a blameless postmortem",
                "description": "Document the game-day incident: timeline, impact, root cause, and action items.",
                "acceptance_criteria": "A blameless postmortem with a timeline and concrete follow-ups exists.",
                "hint": "Focus on systems, not people. Capture timeline, contributing factors, and specific, owned action items. Learning > blame.",
                "order": 6,
                "depends_on": "SRE-5",
            },
        ],
    },

