    {
        "technology_slug": "prompt-engineering",
        "title": "Prompt Engineering Fundamentals",
        "slug": "prompt-fundamentals",
        "architecture_type": "custom",
        "description": (
            "Learn to get reliable results from AI assistants. Cover clear instructions, context, roles, "
            "examples, and iteration, building a reusable prompt for a real task. The foundation of working "
            "effectively with LLMs like Claude."
        ),
        "objectives": [
            "Write clear, specific instructions",
            "Provide useful context and constraints",
            "Use roles and few-shot examples",
            "Iterate systematically on a prompt",
        ],
        "difficulty": "beginner",
        "estimated_hours": 2,
        "order": 1,
        "tasks": [
            {
                "jira_key": "PE-1",
                "title": "Write a clear instruction",
                "description": "Turn a vague request into a specific, unambiguous instruction for a concrete task.",
                "acceptance_criteria": "The prompt states the task, audience, and desired output precisely.",
                "hint": "Specify the task, the audience, the length, and the format. 'Summarise' is vague; 'Summarise in 3 bullets for a busy exec' is clear.",
                "order": 1,
            },
            {
                "jira_key": "PE-2",
                "title": "Add context and constraints",
                "description": "Supply the background the model needs and constrain the response (length, tone, scope).",
                "acceptance_criteria": "The prompt includes relevant context and explicit constraints.",
                "hint": "Models can't read your mind. Include the source text, the goal, and limits ('max 100 words', 'no jargon'). Context beats cleverness.",
                "order": 2,
                "depends_on": "PE-1",
            },
            {
                "jira_key": "PE-3",
                "title": "Assign a role",
                "description": "Use a role/persona to steer expertise and tone.",
                "acceptance_criteria": "A role framing measurably changes the response style appropriately.",
                "hint": "'You are a senior SRE reviewing a runbook' primes relevant expertise and tone. Roles set expectations for depth and vocabulary.",
                "order": 3,
                "depends_on": "PE-1",
            },
            {
                "jira_key": "PE-4",
                "title": "Use few-shot examples",
                "description": "Provide input/output examples so the model matches your desired pattern.",
                "acceptance_criteria": "Examples make the output follow the demonstrated format consistently.",
                "hint": "Show 2-3 examples of input → desired output. Few-shot is the most reliable way to lock in a format the model keeps drifting from.",
                "order": 4,
                "depends_on": "PE-2",
            },
            {
                "jira_key": "PE-5",
                "title": "Iterate on failures",
                "description": "Identify where a prompt underperforms and revise it methodically.",
                "acceptance_criteria": "A revised prompt fixes a specific observed failure without regressing others.",
                "hint": "Change one thing at a time and compare. Add a constraint or example targeting the exact failure. Prompting is empirical — test and refine.",
                "order": 5,
                "depends_on": "PE-4",
            },
            {
                "jira_key": "PE-6",
                "title": "Build a reusable prompt",
                "description": "Generalise your tested prompt into a template with placeholders for reuse.",
                "acceptance_criteria": "A parameterised prompt template works across several inputs.",
                "hint": "Replace specifics with {placeholders}. A good template captures the structure once so you don't re-discover it each time.",
                "order": 6,
                "depends_on": "PE-5",
            },
        ],
    },
