# Guided projects for technologies that previously had none (aws, postgresql,
# mysql, react, nodejs, ai-ml, data-science, nmap, sqlite, peoplesoft, wireshark).
# Kept in a separate module to keep this file reviewable; appended here so the
# seeder and its integrity tests treat them identically to the originals.
from apps.question_bank.management.commands.project_data_extra import EXTRA_PROJECTS  # noqa: E402

PROJECTS = PROJECTS + EXTRA_PROJECTS


class Command(BaseCommand):
    help = "Seed end-to-end guided projects (5+ per technology, zero-to-hero, plus cross-tech capstones)"

    def handle(self, *args, **options):
        created_count = 0
        updated_count = 0
        skipped_count = 0
        task_count = 0
        for proj_src in PROJECTS:
            # Copy so the module-level PROJECTS list is never mutated (keeps the
            # command idempotent and safe to run multiple times in one process).
            proj_data = dict(proj_src)
            tech_slug = proj_data.pop("technology_slug")
            tasks_data = proj_data.pop("tasks")
            try:
                tech = Technology.objects.get(slug=tech_slug)
            except Technology.DoesNotExist:
                self.stderr.write(self.style.WARNING(
                    f"Technology '{tech_slug}' not found — skipping project '{proj_data['title']}'"
                ))
                skipped_count += 1
                continue

            project, created = Project.objects.update_or_create(
                slug=proj_data["slug"],
                defaults={**proj_data, "technology": tech},
            )

            # Pass 1: create/update every task without its depends_on link, so all
            # referenced tasks exist before we wire up dependencies.
            for task_src in tasks_data:
                task_data = {k: v for k, v in task_src.items() if k != "depends_on"}
                ProjectTask.objects.update_or_create(
                    project=project,
                    jira_key=task_data["jira_key"],
                    defaults=task_data,
                )
                task_count += 1

            # Pass 2: resolve depends_on (a jira_key string) into the actual ProjectTask.
            for task_src in tasks_data:
                dep_key = task_src.get("depends_on")
                if not dep_key:
                    continue
                try:
                    task = ProjectTask.objects.get(project=project, jira_key=task_src["jira_key"])
                    dep = ProjectTask.objects.get(project=project, jira_key=dep_key)
                except ProjectTask.DoesNotExist:
                    self.stderr.write(self.style.WARNING(
                        f"  depends_on '{dep_key}' not found for {task_src['jira_key']} "
                        f"in '{project.title}' — leaving unset"
                    ))
                    continue
                if task.depends_on_id != dep.id:
                    task.depends_on = dep
                    task.save(update_fields=["depends_on"])

            # Give the project a launchable environment: an active scenario of its
            # technology, so "Start project" opens that tech's lab (terminal /
            # simulation / coding IDE / VMware / Grafana). Prefer a FREE scenario so
            # Start works for any signed-in user without a subscription; only fall
            # back to a paid one if the technology has no free scenario.
            base = Scenario.objects.filter(technology=tech, is_active=True)
            free_scn = base.filter(is_free=True).order_by("difficulty", "id").first()
            current = project.lab_scenario
            # Set when unset; also self-heal earlier auto-links that landed on a
            # paid scenario (the lab_scenario feature is new — those were never an
            # explicit choice) by re-pointing them to a free one when available.
            needs_link = current is None or (
                free_scn is not None and current is not None and not current.is_free
            )
            if needs_link:
                env_scn = free_scn or base.order_by("difficulty", "id").first()
                if env_scn is not None and env_scn.id != project.lab_scenario_id:
                    project.lab_scenario = env_scn
                    project.save(update_fields=["lab_scenario"])

            if created:
                created_count += 1
                self.stdout.write(self.style.SUCCESS(
                    f"  Created: {project.title} [{tech.name}] ({len(tasks_data)} tasks)"
                ))
            else:
                updated_count += 1
                self.stdout.write(f"  Updated: {project.title} [{tech.name}] ({len(tasks_data)} tasks)")

        self.stdout.write(self.style.SUCCESS(
            f"\nProjects seeded: {created_count} created, {updated_count} updated, "
            f"{skipped_count} skipped, {task_count} tasks total."
        ))
